func loadConfigFile(path string) (map[string][]string, error) {
	ext := strings.ToLower(filepath.Ext(path))
	var parse func([]byte) (map[string][]string, error)
	switch ext {
	case ".json": parse = parseJSONConfig
	case ".yaml", ".yml": parse = parseYAMLConfig
	default:
		return nil, &ConfigError{Path: path, kind: ErrUnsupportedConfigFormat, msg: ...}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, &ConfigError{Path: path, kind: ErrConfigIO, msg: fmt.Sprintf("command: cannot read config file %q: %v", path, err)}
	}
	vals, err := parse(data)
	if err != nil {
		return nil, &ConfigError{Path: path, kind: ErrInvalidConfig, msg: fmt.Sprintf("command: invalid config file %q: %v", path, err)}
	}
	return vals, nil
}
