func parseYAMLConfig(data []byte) (map[string][]string, error) {
	var doc yaml.Node
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return nil, err
	}
	if len(doc.Content) == 0 {
		return nil, errors.New("empty document")
	}
	root := doc.Content[0]
	if root.Kind != yaml.MappingNode {
		return nil, errors.New("top-level value must be a mapping")
	}
	out := make(map[string][]string)
	for i := 0; i+1 < len(root.Content); i += 2 {
		kn, vn := root.Content[i], root.Content[i+1]
		key, ok, err := yamlConfigKey(kn)
		...
		if _, dup := out[key]; dup { return nil, fmt.Errorf("duplicate key %q", key) }
		vals, err := yamlConfigValues(vn)
		out[key] = vals
	}
	return out, nil
}
