var v any
if err := n.Decode(&v); err != nil { return "", err }
switch t := v.(type) {
case int: return strconv.Itoa(t)
case int64: return strconv.FormatInt(t, 10)
case uint64: return strconv.FormatUint(t, 10)
case float64: return strconv.FormatFloat(t, 'f', -1, 64)
case bool: return strconv.FormatBool(t)
case string: return t
default: return n.Value, nil
}
```

